# task-{task_id}.py
# Task ID: {task_id}
# Solution: Anti-diagonal pattern extraction and mod expansion

def transform(grid):
    # Extract anti-diagonal pattern from input
    H = len(grid)
    W = len(grid[0])
    anti_values = {}
    for r in range(H):
        for c in range(W):
            val = grid[r][c]
            if val != 0:
                anti_values[r-c] = val

    # Find best modulus m
    best_mod = None
    best_pattern = None
    for m in range(2, 9):
        mod_pattern = {}
        valid = True
        for d, v in anti_values.items():
            mod_d = d % m
            if mod_d in mod_pattern:
                if mod_pattern[mod_d] != v:
                    valid = False
                    break
            else:
                mod_pattern[mod_d] = v

        if valid and len(mod_pattern) >= 4:
            values = [mod_pattern.get(i) for i in range(m)]
            if all(v is not None for v in values):
                best_mod = m
                best_pattern = values
                break

    # Generate output
    if best_pattern is not None and all(v is not None for v in best_pattern):
        output = [[best_pattern[(r-c) % len(best_pattern)] for c in range(W)] for r in range(H)]
    else:
        output = [[anti_values.get(r-c, 0) for c in range(W)] for r in range(H)]

    return output
